import { PDFDict, PDFDocument, PDFHexString, PDFName, PDFString, type PDFPage } from "pdf-lib";

/**
 * Test fixtures generated by our own code with pdf-lib (Spec 007 acceptance tests 1 and 5).
 * Every file here is built from scratch; nothing is copied from another workflow. Content
 * streams are written by hand so each fixture contains exactly the construct under test.
 */

export type Box = readonly [number, number, number, number];

const XMP_NS = {
  pdfaid: "http://www.aiim.org/pdfa/ns/id/",
  pdfxid: "http://www.npes.org/pdfx/ns/id/",
  pdf: "http://ns.adobe.com/pdf/1.3/",
} as const;

async function newDocument(): Promise<PDFDocument> {
  return PDFDocument.create({ updateMetadata: false });
}

function setContent(doc: PDFDocument, page: PDFPage, content: string | Uint8Array, resources: PDFDict): void {
  page.node.set(PDFName.of("Contents"), doc.context.register(doc.context.flateStream(content)));
  page.node.set(PDFName.of("Resources"), resources);
}

function setBox(doc: PDFDocument, page: PDFPage, name: string, box: Box): void {
  page.node.set(PDFName.of(name), doc.context.obj([...box]));
}

function infoDict(doc: PDFDocument): PDFDict {
  const existing = doc.context.lookup(doc.context.trailerInfo.Info);
  if (existing instanceof PDFDict) return existing;
  const info = doc.context.obj({});
  doc.context.trailerInfo.Info = doc.context.register(info);
  return info;
}

function setTrailerId(doc: PDFDocument): void {
  const id = PDFHexString.of("00112233445566778899aabbccddeeff");
  doc.context.trailerInfo.ID = doc.context.obj([id, id]);
}

function setXmp(doc: PDFDocument, properties: Partial<Record<keyof typeof XMP_NS, Record<string, string>>>): void {
  const descriptions = Object.entries(properties)
    .map(([prefix, values]) => {
      const elements = Object.entries(values ?? {})
        .map(([key, value]) => `   <${prefix}:${key}>${value}</${prefix}:${key}>`)
        .join("\n");
      return `  <rdf:Description rdf:about="" xmlns:${prefix}="${XMP_NS[prefix as keyof typeof XMP_NS]}">\n${elements}\n  </rdf:Description>`;
    })
    .join("\n");
  const packet =
    `<?xpacket begin="﻿" id="W5M0MpCehiHzreSzNTczkc9d"?>\n` +
    `<x:xmpmeta xmlns:x="adobe:ns:meta/">\n <rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">\n` +
    `${descriptions}\n </rdf:RDF>\n</x:xmpmeta>\n<?xpacket end="w"?>`;
  // Metadata streams stay unfiltered so any reader can find them (ISO 19005-2 §6.6.2.1).
  const stream = doc.context.stream(new TextEncoder().encode(packet), { Type: "Metadata", Subtype: "XML" });
  doc.catalog.set(PDFName.of("Metadata"), doc.context.register(stream));
}

/** Saves without object streams. `version` rewrites the header in place (same length, so offsets hold). */
async function save(doc: PDFDocument, version?: `${number}.${number}`): Promise<Uint8Array> {
  const bytes = await doc.save({ useObjectStreams: false });
  if (version) {
    if (version.length !== 3) throw new RangeError(`header version must be like 1.6, got ${version}`);
    bytes.set(new TextEncoder().encode(version), "%PDF-".length);
  }
  return bytes;
}

function grayPixels(widthPx: number, heightPx: number): Uint8Array {
  return Uint8Array.from({ length: widthPx * heightPx }, (_, i) => (i * 37 + Math.floor(i / widthPx) * 11) % 256);
}

function hex(bytes: Uint8Array): string {
  return [...bytes].map((b) => b.toString(16).padStart(2, "0")).join("");
}

// ---------------------------------------------------------------------------------------------

export interface ImageFixtureOptions {
  widthPx: number;
  heightPx: number;
  placedWidthPt: number;
  placedHeightPt: number;
  /** `page`: a `Do` on the page; `form`: inside a Form XObject whose `/Matrix` places it; `inline`: `BI … EI`. */
  placement?: "page" | "form" | "inline";
}

const MARGIN_PT = 36;

/** One 8-bit grey image placed at the given size. Effective ppi = px × 72 / pt. */
export async function imageFixture(options: ImageFixtureOptions): Promise<Uint8Array> {
  const { widthPx: w, heightPx: h, placedWidthPt: pw, placedHeightPt: ph } = options;
  const doc = await newDocument();
  const ctx = doc.context;
  const page = doc.addPage([pw + 2 * MARGIN_PT, ph + 2 * MARGIN_PT]);
  const pixels = grayPixels(w, h);
  const placement = options.placement ?? "page";

  if (placement === "inline") {
    const content = `q ${pw} 0 0 ${ph} ${MARGIN_PT} ${MARGIN_PT} cm\nBI /W ${w} /H ${h} /CS /G /BPC 8 /F /AHx ID\n${hex(pixels)}>\nEI Q\n`;
    setContent(doc, page, content, ctx.obj({}));
    return save(doc);
  }

  const image = ctx.register(
    ctx.flateStream(pixels, { Type: "XObject", Subtype: "Image", Width: w, Height: h, ColorSpace: "DeviceGray", BitsPerComponent: 8 }),
  );
  if (placement === "page") {
    setContent(doc, page, `q ${pw} 0 0 ${ph} ${MARGIN_PT} ${MARGIN_PT} cm /Im0 Do Q\n`, ctx.obj({ XObject: { Im0: image } }));
    return save(doc);
  }
  const form = ctx.register(
    ctx.flateStream("q /Im0 Do Q\n", {
      Type: "XObject",
      Subtype: "Form",
      BBox: [0, 0, 1, 1],
      Matrix: [pw, 0, 0, ph, MARGIN_PT, MARGIN_PT],
      Resources: { XObject: { Im0: image } },
    }),
  );
  setContent(doc, page, "/Fm0 Do\n", ctx.obj({ XObject: { Fm0: form } }));
  return save(doc);
}

export interface FontFixtureOptions {
  /** `unembedded`: a TrueType font without a font file; `type3`: glyphs defined in the file. */
  font: "unembedded" | "type3";
  /** Text rendering mode (ISO 32000-1 §9.3.6); 3 is invisible. Default 0. */
  textRender?: number;
}

/** One line of text in a single font. */
export async function fontFixture(options: FontFixtureOptions): Promise<Uint8Array> {
  const doc = await newDocument();
  const ctx = doc.context;
  const page = doc.addPage([300, 100]);
  let font;
  if (options.font === "unembedded") {
    const descriptor = ctx.obj({
      Type: "FontDescriptor",
      FontName: "ExampleSans",
      Flags: 32,
      FontBBox: [-100, -200, 1000, 900],
      ItalicAngle: 0,
      Ascent: 800,
      Descent: -200,
      CapHeight: 700,
      StemV: 80,
    });
    font = ctx.obj({
      Type: "Font",
      Subtype: "TrueType",
      BaseFont: "ExampleSans",
      FirstChar: 32,
      LastChar: 126,
      Widths: Array.from({ length: 95 }, () => 500),
      Encoding: "WinAnsiEncoding",
      FontDescriptor: ctx.register(descriptor),
    });
  } else {
    const glyph = ctx.register(ctx.flateStream("1000 0 0 0 1000 1000 d1 0 0 1000 1000 re f\n"));
    font = ctx.obj({
      Type: "Font",
      Subtype: "Type3",
      FontBBox: [0, 0, 1000, 1000],
      FontMatrix: [0.001, 0, 0, 0.001, 0, 0],
      CharProcs: { square: glyph },
      Encoding: { Type: "Encoding", Differences: [65, "square"] },
      FirstChar: 65,
      LastChar: 65,
      Widths: [1000],
      Resources: {},
    });
  }
  const content = `BT /F1 24 Tf ${options.textRender ?? 0} Tr 36 36 Td (AAA) Tj ET\n`;
  setContent(doc, page, content, ctx.obj({ Font: { F1: ctx.register(font) } }));
  return save(doc);
}

/** Text converted to outlines: filled paths, no font resource. */
export async function outlinedTextFixture(): Promise<Uint8Array> {
  const doc = await newDocument();
  const page = doc.addPage([300, 100]);
  setContent(doc, page, "0 0 0 rg 36 36 m 60 36 l 48 64 l h f 70 36 m 94 36 l 82 64 l h f\n", doc.context.obj({}));
  return save(doc);
}

export interface PageBoxesFixtureOptions {
  mediaBox: Box;
  bleedBox?: Box;
  trimBox?: Box;
  /** Put the MediaBox on the page tree root instead of the page (ISO 32000-1 §7.7.3.4). */
  inheritMediaBox?: boolean;
}

export async function pageBoxesFixture(options: PageBoxesFixtureOptions): Promise<Uint8Array> {
  const doc = await newDocument();
  const page = doc.addPage();
  if (options.inheritMediaBox) {
    page.node.delete(PDFName.of("MediaBox"));
    doc.catalog.Pages().set(PDFName.of("MediaBox"), doc.context.obj([...options.mediaBox]));
  } else {
    setBox(doc, page, "MediaBox", options.mediaBox);
  }
  if (options.bleedBox) setBox(doc, page, "BleedBox", options.bleedBox);
  if (options.trimBox) setBox(doc, page, "TrimBox", options.trimBox);
  const [x0, y0, x1, y1] = options.mediaBox;
  setContent(doc, page, `0 0 0 1 k ${x0} ${y0} ${x1 - x0} ${y1 - y0} re f\n`, doc.context.obj({}));
  return save(doc);
}

export interface SeparationFixtureOptions {
  /** Default `CutContourTest`. */
  colorant?: string;
  /** `separation`: `[/Separation name …]`; `devicen`: `[/DeviceN [name /Spot B] …]`. */
  space?: "separation" | "devicen";
}

/** A rectangle stroked in a named colorant, the way cut contours are usually drawn. */
export async function separationFixture(options: SeparationFixtureOptions = {}): Promise<Uint8Array> {
  const doc = await newDocument();
  const ctx = doc.context;
  const page = doc.addPage([200, 200]);
  const colorant = options.colorant ?? "CutContourTest";
  let space;
  let tint: string;
  if (options.space === "devicen") {
    const fn = ctx.register(
      ctx.flateStream("{ pop pop 0 1 0 0 }", { FunctionType: 4, Domain: [0, 1, 0, 1], Range: [0, 1, 0, 1, 0, 1, 0, 1] }),
    );
    space = ctx.obj(["DeviceN", [colorant, "Spot B"], "DeviceCMYK", fn]);
    tint = "1 0";
  } else {
    const fn = ctx.obj({ FunctionType: 2, Domain: [0, 1], C0: [0, 0, 0, 0], C1: [0, 1, 0, 0], N: 1 });
    space = ctx.obj(["Separation", colorant, "DeviceCMYK", fn]);
    tint = "1";
  }
  const content = `0 0 0 0.2 k 20 20 160 160 re f /CS0 CS ${tint} SCN 0.5 w 20 20 160 160 re S\n`;
  setContent(doc, page, content, ctx.obj({ ColorSpace: { CS0: space } }));
  return save(doc);
}

export interface TransparencyFixtureOptions {
  fillAlpha?: number;
  blendMode?: string;
  overprint?: boolean;
  pageGroup?: boolean;
}

export async function transparencyFixture(options: TransparencyFixtureOptions = {}): Promise<Uint8Array> {
  const doc = await newDocument();
  const ctx = doc.context;
  const page = doc.addPage([200, 200]);
  const gs: Record<string, number | boolean | string> = { Type: "ExtGState" };
  if (options.fillAlpha !== undefined) gs.ca = options.fillAlpha;
  if (options.blendMode) gs.BM = options.blendMode;
  if (options.overprint) {
    gs.OP = true;
    gs.op = true;
    gs.OPM = 1;
  }
  if (options.pageGroup) page.node.set(PDFName.of("Group"), ctx.obj({ Type: "Group", S: "Transparency", CS: "DeviceCMYK" }));
  setContent(doc, page, "/GS0 gs 0 1 0 0 k 20 20 100 100 re f\n", ctx.obj({ ExtGState: { GS0: ctx.register(ctx.obj(gs)) } }));
  return save(doc);
}

export interface ConformanceFixtureOptions {
  /** `complete: false` leaves out required entries, so the claim fails the structural check. */
  complete: boolean;
}

/** A PDF/X-4 claim (ISO 15930-7): Info and XMP version keys, a GTS_PDFX output intent, TrimBox, /ID, /Trapped. */
export async function pdfxFixture(options: ConformanceFixtureOptions): Promise<Uint8Array> {
  const doc = await newDocument();
  const ctx = doc.context;
  const page = doc.addPage([300, 300]);
  setContent(doc, page, "0 0 0 1 k 20 20 260 260 re f\n", ctx.obj({}));
  const info = infoDict(doc);
  info.set(PDFName.of("GTS_PDFXVersion"), PDFString.of("PDF/X-4"));
  info.set(PDFName.of("Trapped"), PDFName.of("False"));
  setXmp(doc, { pdfxid: { GTS_PDFXVersion: "PDF/X-4" }, pdf: { Trapped: "False" } });
  if (options.complete) {
    setBox(doc, page, "TrimBox", [10, 10, 290, 290]);
    setTrailerId(doc);
    const intent = ctx.obj({
      Type: "OutputIntent",
      S: "GTS_PDFX",
      OutputConditionIdentifier: PDFString.of("CGATS TR 001"),
      RegistryName: PDFString.of("http://www.color.org"),
      Info: PDFString.of("Characterized printing condition"),
    });
    doc.catalog.set(PDFName.of("OutputIntents"), ctx.obj([ctx.register(intent)]));
  }
  return save(doc, "1.6");
}

/** A PDF/A-2b claim (ISO 19005-2) on a page without device colour, so no output intent is needed. */
export async function pdfaFixture(options: ConformanceFixtureOptions): Promise<Uint8Array> {
  const doc = await newDocument();
  const page = doc.addPage([300, 300]);
  setContent(doc, page, "", doc.context.obj({}));
  setXmp(doc, { pdfaid: options.complete ? { part: "2", conformance: "B" } : { part: "2" } });
  setTrailerId(doc);
  return save(doc, "1.7");
}

export interface CorpusEntry {
  name: string;
  bytes: Uint8Array;
}

/** Our own conformance corpus for differential testing against an independent validator. */
export async function conformanceCorpus(): Promise<CorpusEntry[]> {
  return [
    { name: "pdfx4-complete", bytes: await pdfxFixture({ complete: true }) },
    { name: "pdfx4-incomplete", bytes: await pdfxFixture({ complete: false }) },
    { name: "pdfa2b-complete", bytes: await pdfaFixture({ complete: true }) },
    { name: "pdfa2-no-conformance", bytes: await pdfaFixture({ complete: false }) },
    { name: "no-claim", bytes: await outlinedTextFixture() },
  ];
}
